[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Lichess Chess Game Analytics: Patterns of Victory, Openings, and Player Dynamics</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
  <style>
    :root {
      --bg: #0f1117;
      --surface: #1a1d2e;
      --surface2: #242840;
      --border: #2e3256;
      --accent: #6c8ebf;
      --accent2: #e8a838;
      --white-color: #7ec8e3;
      --black-color: #e07070;
      --draw-color: #a0a0a0;
      --text: #d8dce8;
      --text-muted: #8890a8;
      --success: #5cb85c;
      --warn: #e8a838;
      --danger: #e07070;
      --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
      --mono: 'Cascadia Code', 'Fira Code', monospace;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      background: var(--bg);
      color: var(--text);
      font-family: var(--font);
      line-height: 1.6;
      font-size: 15px;
    }

    /* ── Layout ── */
    .wrapper { max-width: 1200px; margin: 0 auto; padding: 0 24px 80px; }

    /* ── Hero ── */
    .hero {
      background: linear-gradient(135deg, #0f1117 0%, #1a1d2e 40%, #1e2240 100%);
      border-bottom: 2px solid var(--border);
      padding: 60px 24px 48px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '♟';
      position: absolute;
      font-size: 280px;
      opacity: 0.04;
      top: -40px;
      left: 50%;
      transform: translateX(-50%);
    }
    .hero-tag {
      display: inline-block;
      background: var(--accent);
      color: #fff;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 2px;
      text-transform: uppercase;
      padding: 4px 12px;
      border-radius: 4px;
      margin-bottom: 20px;
    }
    .hero h1 {
      font-size: clamp(24px, 4vw, 42px);
      font-weight: 800;
      color: #fff;
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }
    .hero-sub {
      color: var(--text-muted);
      font-size: 16px;
      max-width: 600px;
      margin: 0 auto 32px;
    }
    .hero-meta {
      display: flex;
      justify-content: center;
      gap: 32px;
      flex-wrap: wrap;
    }
    .hero-meta-item { text-align: center; }
    .hero-meta-item .val {
      font-size: 28px;
      font-weight: 800;
      color: var(--accent2);
      display: block;
    }
    .hero-meta-item .lbl {
      font-size: 12px;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 1px;
    }

    /* ── Nav ── */
    .toc {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px 24px;
      margin: 32px 0;
    }
    .toc h3 {
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--text-muted);
      margin-bottom: 12px;
    }
    .toc ol { padding-left: 20px; }
    .toc li { margin: 6px 0; }
    .toc a { color: var(--accent); text-decoration: none; font-size: 14px; }
    .toc a:hover { text-decoration: underline; }

    /* ── Section ── */
    .section { margin: 48px 0; }
    .section-header {
      display: flex;
      align-items: center;
      gap: 14px;
      margin-bottom: 24px;
      padding-bottom: 14px;
      border-bottom: 2px solid var(--border);
    }
    .section-num {
      background: var(--accent);
      color: #fff;
      font-size: 13px;
      font-weight: 800;
      width: 32px;
      height: 32px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .section h2 {
      font-size: 22px;
      font-weight: 700;
      color: #fff;
    }

    /* ── Cards ── */
    .card-grid {
      display: grid;
      gap: 16px;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      margin-bottom: 24px;
    }
    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px;
    }
    .card .card-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--text-muted);
      margin-bottom: 8px;
    }
    .card .card-val {
      font-size: 30px;
      font-weight: 800;
      color: #fff;
      line-height: 1;
      margin-bottom: 4px;
    }
    .card .card-sub { font-size: 13px; color: var(--text-muted); }
    .card.accent-white { border-top: 3px solid var(--white-color); }
    .card.accent-black { border-top: 3px solid var(--black-color); }
    .card.accent-draw  { border-top: 3px solid var(--draw-color); }
    .card.accent-gold  { border-top: 3px solid var(--accent2); }
    .card.accent-blue  { border-top: 3px solid var(--accent); }

    /* ── Chart containers ── */
    .chart-wrap {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 24px;
      margin-bottom: 24px;
    }
    .chart-wrap h3 {
      font-size: 15px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 18px;
    }
    .chart-wrap p.note {
      font-size: 12px;
      color: var(--text-muted);
      margin-top: 12px;
    }
    .chart-row {
      display: grid;
      gap: 16px;
      grid-template-columns: 1fr 1fr;
    }
    @media (max-width: 750px) { .chart-row { grid-template-columns: 1fr; } }

    /* ── Tables ── */
    .table-wrap {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      overflow: hidden;
      margin-bottom: 24px;
    }
    .table-wrap h3 {
      font-size: 15px;
      font-weight: 700;
      color: #fff;
      padding: 16px 20px;
      border-bottom: 1px solid var(--border);
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13.5px;
    }
    thead th {
      background: var(--surface2);
      color: var(--text-muted);
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      padding: 10px 16px;
      text-align: left;
    }
    tbody tr { border-bottom: 1px solid var(--border); }
    tbody tr:last-child { border-bottom: none; }
    tbody tr:hover { background: var(--surface2); }
    tbody td { padding: 10px 16px; }
    .td-num { font-family: var(--mono); text-align: right; }
    .badge {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 11px;
      font-weight: 700;
    }
    .badge-white { background: rgba(126,200,227,0.2); color: var(--white-color); }
    .badge-black { background: rgba(224,112,112,0.2); color: var(--black-color); }
    .badge-draw  { background: rgba(160,160,160,0.15); color: var(--draw-color); }
    .badge-even  { background: rgba(108,142,191,0.2); color: var(--accent); }

    /* ── Progress bars ── */
    .bar-wrap { display: flex; gap: 2px; height: 22px; border-radius: 4px; overflow: hidden; }
    .bar-seg {
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: rgba(255,255,255,0.9);
      transition: width 0.3s;
      white-space: nowrap;
      overflow: hidden;
    }
    .bar-white { background: var(--white-color); }
    .bar-black { background: var(--black-color); }
    .bar-draw  { background: var(--draw-color); }

    /* ── Insight boxes ── */
    .insight {
      background: linear-gradient(135deg, var(--surface) 0%, var(--surface2) 100%);
      border: 1px solid var(--border);
      border-left: 4px solid var(--accent);
      border-radius: 0 8px 8px 0;
      padding: 14px 18px;
      margin-bottom: 16px;
      font-size: 14px;
    }
    .insight strong { color: var(--accent2); }
    .insight.warn { border-left-color: var(--warn); }
    .insight.success { border-left-color: var(--success); }
    .insight.danger { border-left-color: var(--danger); }

    /* ── Key Findings ── */
    .finding {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px 24px;
      margin-bottom: 16px;
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 16px;
      align-items: start;
    }
    .finding-icon {
      font-size: 28px;
      line-height: 1;
    }
    .finding h4 {
      font-size: 15px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 6px;
    }
    .finding p { font-size: 14px; color: var(--text-muted); }
    .finding strong { color: var(--text); }

    /* ── Footer ── */
    footer {
      background: var(--surface);
      border-top: 1px solid var(--border);
      text-align: center;
      padding: 24px;
      color: var(--text-muted);
      font-size: 13px;
      margin-top: 60px;
    }
  </style>
</head>
<body>

<!-- ═══════════════════════════ HERO ═══════════════════════════ -->
<div class="hero">
  <div class="hero-tag">Analytical Report</div>
  <h1>Lichess Chess Game Analytics:<br>Patterns of Victory, Openings, and Player Dynamics</h1>
  <p class="hero-sub">A data-forward examination of 20,058 Lichess games — color advantage, rating dynamics, opening strategies, and time control effects.</p>
  <div class="hero-meta">
    <div class="hero-meta-item"><span class="val">20,058</span><span class="lbl">Total Games</span></div>
    <div class="hero-meta-item"><span class="val">80.5%</span><span class="lbl">Rated Games</span></div>
    <div class="hero-meta-item"><span class="val">52.3%</span><span class="lbl">White Win Rate (decisive)</span></div>
    <div class="hero-meta-item"><span class="val">4.7%</span><span class="lbl">Draw Rate</span></div>
    <div class="hero-meta-item"><span class="val">60.5</span><span class="lbl">Avg. Turns / Game</span></div>
  </div>
</div>

<div class="wrapper">

  <!-- Table of Contents -->
  <div class="toc">
    <h3>Contents</h3>
    <ol>
      <li><a href="#overview">Dataset Overview &amp; Game Distribution</a></li>
      <li><a href="#color-advantage">White vs. Black: The First-Move Advantage</a></li>
      <li><a href="#rating-analysis">Rating Dynamics and Their Impact on Outcomes</a></li>
      <li><a href="#opening-strategy">Opening Analysis: Popular Openings and Their Success Rates</a></li>
      <li><a href="#time-control">Time Control Patterns and Game Characteristics</a></li>
      <li><a href="#key-findings">Key Findings and Strategic Takeaways</a></li>
    </ol>
  </div>

  <!-- ═══════════════════════════ SECTION 1 ═══════════════════════════ -->
  <div class="section" id="overview">
    <div class="section-header">
      <div class="section-num">1</div>
      <h2>Dataset Overview &amp; Game Distribution</h2>
    </div>

    <div class="card-grid">
      <div class="card accent-gold">
        <div class="card-label">Total Games</div>
        <div class="card-val">20,058</div>
        <div class="card-sub">16 columns per record</div>
      </div>
      <div class="card accent-blue">
        <div class="card-label">Rated Games</div>
        <div class="card-val">16,155</div>
        <div class="card-sub">80.54% of dataset</div>
      </div>
      <div class="card accent-draw">
        <div class="card-label">Casual / Unrated</div>
        <div class="card-val">3,903</div>
        <div class="card-sub">19.46% of dataset</div>
      </div>
      <div class="card accent-white">
        <div class="card-label">Avg. Turns / Game</div>
        <div class="card-val">60.5</div>
        <div class="card-sub">Half-moves (plies)</div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-wrap">
        <h3>Winner Distribution</h3>
        <canvas id="winnerPie" height="220"></canvas>
        <p class="note">n = 20,058 games. White: 10,001 · Black: 9,107 · Draw: 950</p>
      </div>
      <div class="chart-wrap">
        <h3>Victory Status Distribution</h3>
        <canvas id="victoryPie" height="220"></canvas>
        <p class="note">Resign accounts for over half of all game endings (55.6%).</p>
      </div>
    </div>

    <div class="chart-wrap">
      <h3>Average Game Length by Victory Status (turns)</h3>
      <canvas id="turnsBar" height="130"></canvas>
      <p class="note">Drawn games are 56% longer than resigned games on average, reflecting the positional grind that precedes agreed draws.</p>
    </div>

    <div class="insight">
      The dataset is <strong>heavily skewed toward resignation</strong> as the terminal event (55.6%), which is typical of online blitz chess where players recognize losing positions quickly. Only 31.5% of games reach checkmate. Draws are rare at <strong>4.7%</strong>, a low figure attributable to the predominantly casual and mid-rated player pool where fighting draws are uncommon.
    </div>
  </div>

  <!-- ═══════════════════════════ SECTION 2 ═══════════════════════════ -->
  <div class="section" id="color-advantage">
    <div class="section-header">
      <div class="section-num">2</div>
      <h2>White vs. Black: The First-Move Advantage</h2>
    </div>

    <div class="card-grid">
      <div class="card accent-white">
        <div class="card-label">White Win Rate (all games)</div>
        <div class="card-val">49.86%</div>
        <div class="card-sub">10,001 / 20,058 games</div>
      </div>
      <div class="card accent-black">
        <div class="card-label">Black Win Rate (all games)</div>
        <div class="card-val">45.40%</div>
        <div class="card-sub">9,107 / 20,058 games</div>
      </div>
      <div class="card accent-draw">
        <div class="card-label">Draw Rate</div>
        <div class="card-val">4.74%</div>
        <div class="card-sub">950 / 20,058 games</div>
      </div>
      <div class="card accent-gold">
        <div class="card-label">White Win Rate (decisive only)</div>
        <div class="card-val">52.34%</div>
        <div class="card-sub">10,001 / 19,108 decisive games</div>
      </div>
    </div>

    <!-- Aggregate bar -->
    <div class="chart-wrap">
      <h3>Overall Win Distribution</h3>
      <div class="bar-wrap" style="height:40px;">
        <div class="bar-seg bar-white" style="width:49.86%">White 49.86%</div>
        <div class="bar-seg bar-black" style="width:45.40%">Black 45.40%</div>
        <div class="bar-seg bar-draw"  style="width:4.74%">4.74%</div>
      </div>
      <p class="note" style="margin-top:10px;">Among decisive outcomes only: White 52.34% · Black 47.66%</p>
    </div>

    <!-- By victory status -->
    <div class="chart-wrap">
      <h3>Win Rates by Victory Status</h3>
      <canvas id="victoryStatusWin" height="160"></canvas>
      <p class="note">White's advantage concentrates in checkmates (52.87%) and resignations (52.43%). Timeouts are effectively coin-flip outcomes (48.4% white vs. 49.0% black).</p>
    </div>

    <!-- By rating bracket -->
    <div class="chart-wrap">
      <h3>White Win Rate by Average Rating Bracket</h3>
      <canvas id="ratingBracketWin" height="170"></canvas>
      <p class="note">White's win-rate advantage is highest at the lowest rating bracket (&lt;1000: 52.7%) and narrows progressively toward 2000+ where the gap nearly disappears (46.6% white vs. 45.4% black, with draws absorbing the balance at 8.0%).</p>
    </div>

    <!-- Draw rate by bracket -->
    <div class="chart-wrap">
      <h3>Draw Rate by Average Rating Bracket</h3>
      <canvas id="drawRateBracket" height="140"></canvas>
      <p class="note">Draw rate rises monotonically with rating — from 2.2% below 1000 to 8.0% above 2000 — confirming that higher-rated players are better at converting drawing resources.</p>
    </div>

    <!-- Table of bracket data -->
    <div class="table-wrap">
      <h3>Detailed Breakdown by Rating Bracket</h3>
      <table>
        <thead>
          <tr>
            <th>Rating Bracket</th>
            <th>Games</th>
            <th>White Win%</th>
            <th>Black Win%</th>
            <th>Draw%</th>
            <th>Advantage</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>&lt; 1000</td><td class="td-num">93</td>
            <td class="td-num">52.69%</td><td class="td-num">45.16%</td><td class="td-num">2.15%</td>
            <td><span class="badge badge-white">White +7.5pp</span></td>
